self.addEventListener('install', e => {
  /* ★ONE LOST REQUEST OUT OF SIXTY-FIVE DESTROYED THE WHOLE INSTALL (2026-09-10, measured in a browser).
     `cache.addAll` is ATOMIC: it rejects if ANY entry fails, that rejection escapes waitUntil, and the
     worker goes straight from `installing` to `redundant`. The person is then left with no worker at
     all - no precache, no offline fallback, no network-first copy of the page they were on - and
     nothing anywhere says so. The failure is silent by construction, which is why it survived this long.

     PROVEN, not reasoned: registering under the journey prover's own `offline-3g` emulation (every
     request delayed, roughly one in twelve aborted) gives `registered: true, state: installing,
     finalState: REDUNDANT`, with sw.js itself never among the dropped requests. The same page with the
     routing present but nothing dropped installs and activates normally - so it is the loss that kills
     it, not the instrumentation.

     THE ARITHMETIC IS THE ARGUMENT, and it is not only about a stress test. The list is 65 entries, so
     an install survives only if all 65 land: at offline-3g's 1-in-12 that is (11/12)^65 = 0.35%, which
     is why every offline-3g journey has been walking a platform whose service worker was inert. But at
     a perfectly ordinary 1% request loss it is (0.99)^65 = 52% - HALF of real installs on a plant floor
     failing completely - and at 3% it is 14%. An all-or-nothing install is the wrong shape for the
     connection this product is built for.

     So each file gets one retry (a dropped request is usually unlucky rather than unavailable - the
     same reasoning browser-floor.js uses for a dropped script), and a file that still will not come is
     LEFT OUT instead of taking the install down with it. A worker holding 63 of 65 files is a working
     shell; a worker that never activates is nothing. What is lost is the guarantee that a precached
     file is always present - and the fetch handler already answers that case, because every path
     through it falls back to the network and then to the offline shell. */
  e.waitUntil(caches.open(CACHE_NAME).then(async (cache) => {
    const missed = [];
    await Promise.all(SHELL_FILES.map(async (f) => {
      for (let attempt = 0; attempt < 2; attempt++) {
        try { await cache.add(f); return; } catch (err) { void err; }
      }
      missed.push(f);
    }));
    // say it once, where a developer looking at a half-stocked cache would otherwise have no idea
    if (missed.length) {
      console.warn('[sw] installed with ' + missed.length + ' of ' + SHELL_FILES.length
        + ' shell files missing (the connection dropped them); the worker is active and will fetch them on demand');
    }
  }));
  self.skipWaiting();
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k)))
    )
  );
  self.clients.claim();
});

// Network-first for API and font requests; cache-first for shell
self.addEventListener('fetch', e => {
  const url = e.request.url;
  if (url.includes('supabase.co') || url.includes('fonts.goog') || url.includes('fonts.gstatic')) {
    e.respondWith(fetch(e.request).catch(() => new Response('', { status: 503 })));
    return;
  }
  /* ★THE PUBLIC LIBRARY WAS NEVER CACHEABLE AT ALL (2026-09-09, found walking a learn article's
     adaptability row). SHELL_FILES precaches the app pages and the Filipino dictionaries, and this
     handler is cache-first with a network fallback — but it never WRITES, so a page outside that list
     could never enter the cache no matter how often it was read. Measured on
     learn/ai-quality-and-roi-stage-2-plants: caches.match() found nothing under either shell version, so
     opening it offline served the fallback shell instead of the article. That is backwards for the one
     surface aimed at a plant floor with a bad signal: 54 learn guides and 60 tool pages, all public, all
     read exactly where connectivity is worst. Cache-on-visit costs nothing up front and keeps whatever
     the person actually read. The copy is stored AFTER the response is handed over, so caching can never
     delay or break the page. */
  const _req = e.request;
  const _keepable = _req.method === 'GET'
    && new URL(url).origin === self.location.origin
    && /\/(learn|tools)\//.test(new URL(url).pathname);

  /* ★AN APP PAGE COULD NOT BE CACHED AT ALL, AND A DROPPED REQUEST LOST IT ENTIRELY (2026-09-10,
     measured by a journey walk, not inferred). W3521 - J25 in Lucena on the `offline-3g` condition,
     which delays every request and ABORTS roughly one in twelve - reported `logbook.html` never
     arriving: `landed=` empty, no own links, no hub. The same shape sank W3559 on J9. The reason is
     right here: SHELL_FILES precaches exactly TWO html pages (report-sender, offline-fallback), and
     the cache-on-visit path above is scoped to `/learn/` and `/tools/`, so logbook.html - 404KB, the
     surface a technician opens most - was never in the cache by any route. One dropped asset and the
     person gets the offline shell instead of their work. validate_sw_offline has carried this as a
     standing WARN ("logbook.html is worker-critical but not in SHELL_FILES") for a long time; the
     walk is what put a cost on it.

     WHY NOT JUST PRECACHE THEM: hive.html and logbook.html are 434KB and 404KB, so adding them to
     SHELL_FILES would nearly double the install payload for every user, including the ones who never
     open them - and cache-FIRST (what the branch below does) would then serve yesterday's app HTML
     until the next CACHE_NAME bump, which is a worse failure than the one being fixed. An app page
     changes on every deploy; a learn article does not, which is exactly why cache-first is right for
     one and wrong for the other.

     So app-page NAVIGATIONS are network-FIRST and keep a copy for the bad day: the person always gets
     the live page when the network answers, and gets the last one they actually opened when it does
     not. Costs nothing up front, stores only what was really visited, and cannot serve stale HTML
     while the network works. */
  const _appNav = _req.method === 'GET'
    && _req.mode === 'navigate'
    && new URL(url).origin === self.location.origin
    && !/\/(learn|tools)\//.test(new URL(url).pathname);

  /* ★A SCRIPT 38 PAGES DEPEND ON COULD BE SERVED BY NO ROUTE (2026-09-10, sw-offline L5).
     utils.js (363KB, 38 pages, defines getDb) and companion-launcher.js (99KB, 29 pages) are in no
     SHELL_FILES entry, and the branch below only WRITES for /learn/ and /tools/ - so neither could
     ever enter the cache, and one dropped request left the page throwing `window.getDb is not a
     function` with nothing to fall back on. That is W3122's error under offline-3g exactly.
     Precaching them would bill every install 462KB for files many visitors never open and would then
     serve yesterday's JavaScript until a CACHE_NAME bump; network-first with a kept copy gives the
     same protection with neither cost, which is the argument the _appNav branch already makes for
     app pages. A script ALREADY in SHELL_FILES stays on the cache-first path: it is in the cache from
     install, so routing it through the network would cost first-paint speed to buy a guarantee it has.
     Compared by path SUFFIX because SHELL_FILES entries are origin-root ('/nav-hub.js') while the
     local tester serves the app under /workhive/ - a prefix that has broken SW paths here before. */
  const _scriptPath = new URL(url).pathname;
  const _precachedScript = SHELL_FILES.some((f) => _scriptPath.endsWith(f));
  const _appScript = _req.method === 'GET'
    && _req.destination === 'script'
    && new URL(url).origin === self.location.origin
    && !_precachedScript;

  if (_appNav || _appScript) {
    e.respondWith(
      fetch(_req).then(res => {
        if (res && res.ok && res.type === 'basic') {
          const copy = res.clone();
          const write = caches.open(CACHE_NAME).then(c => c.put(_req, copy)).catch(() => {});
          // same waitUntil caveat as below: attempted while legal, and the write runs regardless
          try { e.waitUntil(write); } catch (_) { /* past the dispatch window: the write still runs */ }
        }
        return res;
      /* ★ignoreSearch IS A NAVIGATION RULE, NOT A CACHE RULE. The comment below earns it for app
         pages: `logbook.html?tab=history` and `logbook.html` are the same document, and the query
         selects a tab the page reads at runtime. For a SCRIPT the opposite holds - a query is
         usually a cache-buster, so `utils.js?v=2` matching a stored `utils.js?v=1` would serve the
         very version someone bumped to get away from. No script on the platform carries a query
         today (checked: zero of them), so this changes nothing now and closes the trap before
         anyone adds the first one. */
      }).catch(() => caches.match(_req, { ignoreSearch: _req.mode === 'navigate' }).then(cached =>
        /* the page they last opened beats the branded shell; the shell beats a blank tab.
           ★ignoreSearch, because a navigation almost never repeats its query. The copy is stored
           under the exact URL that was fetched, so `logbook.html?tab=history` offline would miss a
           cached `logbook.html` and fall through to the shell - the person would be told they are
           offline while their page sat in the cache one character away. On an app NAVIGATION the
           query selects a tab or a filter the page reads at runtime from the SAME document, so the
           cached HTML is the right answer to all of them; it is the data behind it that is stale,
           and that is what the page's own offline signals are for. */
        /* ★AND THE FALLBACK MUST NOT HAND A SCRIPT TAG A PAGE. The branded shell is the right answer
           for a navigation and a catastrophe for a <script src>: the browser would parse HTML as
           JavaScript, throw a syntax error, and the real cause - one lost request - would be nowhere
           in the message. A script with no cached copy gets an honest 503. */
        cached || (_req.mode === 'navigate'
          /* ★A BLANK 503 IS WORSE THAN THE BROWSER'S OWN ERROR PAGE, and until this turn that branch
             could not be reached: the install was atomic, so the shell was either wholly cached or the
             worker never activated at all. Now that a straggler can be left out, the offline fallback
             itself may be the file that is missing - and answering a navigation with an empty 503 paints
             a WHITE PAGE, which tells a person less than Chrome's "no internet" screen does. Handing back
             a network error lets the browser do what it is good at. */
          ? caches.match('/offline-fallback.html').then(f => f || Response.error())
          : new Response('', { status: 503 }))))
    );
    return;
  }

  e.respondWith(
    caches.match(_req).then(cached => cached || fetch(_req).then(res => {
      if (_keepable && res && res.ok && res.type === 'basic') {
        /* ★e.waitUntil() ONLY WORKS WHILE THE EVENT IS STILL DISPATCHING. The first version called it
           in HERE - inside fetch's .then(), which runs a tick after respondWith() already returned - so
           it threw InvalidStateError every time and not one page was ever cached. The .catch() sat on
           caches.open(), not on waitUntil, so the throw escaped and the whole thing failed silently
           while the code read as if it worked. Found by checking the cache after a visit instead of
           trusting the edit. waitUntil is still ATTEMPTED (it is the correct way to keep the worker
           alive when it is legal), and the write happens regardless if it is not. */
        const copy = res.clone();
        const write = caches.open(CACHE_NAME).then(c => c.put(_req, copy)).catch(() => {});
        try { e.waitUntil(write); } catch (_) { /* past the dispatch window: the write still runs */ }
      }
      return res;
    }).catch(() => {
      // Arc S D-lens (D-003): offline AND not precached. For a page navigation, serve
      // the branded offline shell instead of a blank tab; for sub-resources, a 503.
      if (_req.mode === 'navigate') {
        // same reasoning as the branch above: with a partial shell possible, an uncached fallback must
        // give the browser its network error rather than a blank page of our own making
        return caches.match('/offline-fallback.html').then(f => f || Response.error());
      }
      return new Response('', { status: 503 });
    }))
  );
});

// ── Web Push (SERVICE_HAILING P5/G3) ─────────────────────────────────────────
// notify-push (edge fn, VAPID) sends { title, body, url }. Without these handlers a
// delivered push silently no-ops; the click handler focuses an existing tab on the
// target page or opens one — the provider lands on the job-offer console in one tap.
self.addEventListener('push', e => {
  let data = { title: 'WorkHive', body: 'You have a new notification.', url: '/workhive/marketplace-seller.html?tab=services' };
  try { data = Object.assign(data, e.data ? e.data.json() : {}); } catch (_) { /* empty-catch-allow: malformed payload falls back to the generic notification */ }
  e.waitUntil(self.registration.showNotification(data.title, {
    body: data.body,
    icon: '/workhive/brand_assets/workhive-logo-transparent.png',
    badge: '/workhive/brand_assets/workhive-logo-transparent.png',
    data: { url: data.url },
  }));
});

self.addEventListener('notificationclick', e => {
  e.notification.close();
  const target = (e.notification.data && e.notification.data.url) || '/workhive/marketplace-seller.html?tab=services';
  e.waitUntil(clients.matchAll({ type: 'window', includeUncontrolled: true }).then(list => {
    for (const c of list) {
      if (!c.url.includes(target.split('?')[0]) || !('focus' in c)) continue;
      // T105 (2026-08-26): MATCHING ON THE PATH ALONE DROPPED THE DESTINATION. A push's whole
      // point is where it sends you, and every url this worker receives carries that in the
      // QUERY (?tab=services, ?asset=, ?post=). With an existing tab open on the same page at a
      // different tab/record, the old code focused it and returned - so a job-offer push landed
      // the provider on whatever they had been looking at, with nothing to say a destination had
      // been promised and missed. Focus the tab AND navigate it when the query differs.
      var sameTarget = false;
      try { sameTarget = new URL(target, c.url).href === c.url; } catch (_) { sameTarget = c.url.endsWith(target); }
      if (sameTarget || !('navigate' in c)) return c.focus();
      return c.navigate(target).then(cl => (cl && 'focus' in cl) ? cl.focus() : cl).catch(() => c.focus());
    }
    return clients.openWindow(target);
  }));
});
